args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?birthDate WHERE {
  VALUES ?person { dbr:Jean-Baptiste_Le_Prince dbr:Billy_Magoulias }
  OPTIONAL { ?person dbo:birthDate ?d1. }
  OPTIONAL { ?person dbp:birthDate ?d2. }
  OPTIONAL { ?person dbp:born ?d3. }
  BIND(coalesce(?d1, ?d2, ?d3) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = "en") }
}
ORDER BY ?birthDate
LIMIT 1

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?abs WHERE {
  dbr:Jean-Baptiste_Le_Prince dbo:abstract ?abs .
  FILTER(lang(?abs) = "en")
} LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?birthDate WHERE {
  VALUES ?person { dbr:Jean-Baptiste_Le_Prince dbr:Billy_Magoulias }
  OPTIONAL { ?person dbo:birthDate ?d1. }
  OPTIONAL { ?person dbp:birthDate ?d2. }
  OPTIONAL { ?person dbo:abstract ?abs. FILTER(lang(?abs) = "en") }
  BIND(
    IF(BOUND(?d1), ?d1,
      IF(BOUND(?d2), ?d2,
        xsd:date(CONCAT(REPLACE(STR(STRBEFORE(STRAFTER(?abs, "("), "–")), "^.*?([0-9]{4}).*$", "$1"), "-01-01"))
      )
    ) AS ?birthDate
  )
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = "en") }
}
ORDER BY ?birthDate
LIMIT 1

